def outward(incid):
 ei,end=incid; e=edges[ei]; pts=e['pts'] if end==0 else e['pts'][::-1]
 # vector from contracted junction toward the chain
 i=1 if len(pts)>1 else 0
 return np.array([pts[i][1]-pts[0][1], pts[i][0]-pts[0][0]],float) / (np.linalg.norm([pts[i][1]-pts[0][1],pts[i][0]-pts[0][0]])+1e-9)
def best_pairing(items):
 # pair as many half-edges as possible; leave at most one unmatched
 if not items:return [],[]
 if len(items)==1:return [],items[:]
 vec={it:outward(it) for it in items}
 best=(1e9,None,None)
